from pathlib import Path
import datetime,hashlib,json
OUT=Path(__file__).resolve().parent
NOW=datetime.datetime.now(datetime.timezone.utc).isoformat()
C=Path('/tmp/medina-n00-source-cache');OLD=Path('/tmp/medina-n04-source-cache')
rows=[]
def add(i,path,url,publisher,section,passage,population,limits):
 rows.append(dict(id=i,url=url,publisher=publisher,section=section,passage=passage,passage_type='faithful_paraphrase',population=population,limitations=limits,read_at=NOW,sha256=hashlib.sha256(path.read_bytes()).hexdigest(),cache_path=str(path),reader='astra_nephrologie'))
CHH='https://www.hug.ch/sites/interhug/files/2022-09/strategie_microhematurie.pdf'
CHR='https://www.revmed.ch/view/518997/4233572/RMS_419_480.pdf'
FG='https://manuel.cuen.fr/wp-content/uploads/2025/10/CUEN-12e-ed-Chap10-nephropathies-glomerulaires.pdf'
FH='https://manuel.cuen.fr/wp-content/uploads/2025/10/CUEN-12e-ed-Chap7-hematurie.pdf'
FA='https://manuel.cuen.fr/wp-content/uploads/2025/10/CUEN-12e-ed-Chap14-insuffisance-renale-aigue-anurie.pdf'
KD='https://kdigo.org/wp-content/uploads/2017/02/KDIGO-Glomerular-Diseases-Guideline-2021-English.pdf'
add('CH-SEDIMENT',C/'CH-HEMATURIA.raw',CHH,'HUG, médecine de premier recours, 2017','pp.1–4 ; définitions et algorithme','La bandelette doit être confirmée et l’origine appréciée par la morphologie. Les cylindres érythrocytaires et acanthocytes orientent vers le glomérule ; leur absence ne suffit pas à l’exclure. Le stockage et la concentration modifient l’interprétation. Protéinurie, hypertension et baisse de filtration motivent un avis néphrologique.','Adultes en premier recours','Stratégie d’experts de 2017 ; le suivi différé d’une microhématurie isolée ne convient pas à un tableau aigu grave. Les pourcentages morphologiques dépendent de la méthode.')
add('CH-URGENCE',C/'CH-RPGN.raw',CHR,'Halfon et coll., Revue Médicale Suisse 2014','pp.480–482 ; introduction, mécanismes, symptômes et diagnostic','Une perte rapide de fonction avec hématurie et protéinurie exige une évaluation néphrologique urgente. Les lésions capillaires favorisent des croissants extracapillaires ; les atteintes pulmonaires, ORL et systémiques orientent la cause. Une natriurèse ou une fraction d’excrétion sodée basse peut accompagner une glomérulonéphrite.','Glomérulonéphrites rapidement progressives','Source ancienne utilisée pour reconnaissance et mécanismes ; ni incidence transposée à tout syndrome néphritique ni schéma thérapeutique 2014 repris comme standard actuel.')
add('CH-ORIENTATION',OLD/'SSN2025.raw','https://www.swissnephrology.ch/wp/wp-content/uploads/2025/03/Version-2025_Francais_V_17.03.2025_WZ.pdf','Société suisse de néphrologie, 17.03.2025','Figure4, orientation néphrologique','L’insuffisance rénale aiguë ou la chute brutale persistante du débit estimé, l’hématurie glomérulaire et les anomalies persistantes du potassium font partie des motifs d’orientation néphrologique.','Repérage rénal en Suisse','Document principalement consacré à la maladie rénale chronique ; aucune cible tensionnelle chronique transposée au traitement d’une urgence aiguë.')
add('EU-SYNDROMES',C/'FR-GLOM.raw',FG,'CUEN, 12e édition, 2025','pp.169–171, tableau1','Une atteinte glomérulaire associe protéinurie à prédominance albumine et/ou hématurie ; hypertension, œdèmes et baisse de fonction complètent le tableau. Le syndrome néphritique s’installe en quelques jours, avec une rétention hydrosodée et souvent une oligurie. Il est distingué du syndrome néphrotique et de la progression rapide.','Enseignement adulte avec comparaisons pédiatriques','Les tableaux décrivent des présentations typiques ; toutes les manifestations ne sont pas obligatoires et le syndrome ne prouve pas une cause poststreptococcique.')
add('EU-HISTO',C/'FR-GLOM.raw',FG,'CUEN, 12e édition, 2025','pp.172–175 ; biopsie, glomérule normal et lésions','La biopsie précise diagnostic, activité et cicatrices. Endothélium, membrane basale et podocytes forment le filtre ; cellules pariétales et mésangiales ont des fonctions distinctes. Microscopie optique, immunofluorescence et microscopie électronique explorent des dimensions différentes. Proliférations endocapillaire et extracapillaire ne sont pas synonymes.','Glomérulopathies','Les risques et la voie de biopsie sont individualisés par le centre ; ne pas transformer toutes les contre-indications didactiques du tableau en interdictions absolues universelles.')
add('EU-IGA',C/'FR-GLOM.raw',FG,'CUEN, 12e édition, 2025','pp.179–180 ; néphropathie à IgA','L’hématurie récidivante peut être contemporaine d’une infection ORL, souvent dans les 48 heures. D’autres présentations sont possibles ; la biopsie identifie les dépôts d’IgA mésangiaux. La vascularite à IgA ajoute des manifestations extrarénales.','Adultes et enfants selon présentation','Le délai est un indice clinique, pas un critère de confirmation ; les traitements récents spécifiques de l’IgA ne sont pas déduits de ce passage.')
add('EU-RPGN',C/'FR-GLOM.raw',FG,'CUEN, 12e édition, 2025','pp.181–183 ; définition, tableau7 et syndrome réno-pulmonaire','La baisse de fonction en quelques jours ou semaines, avec hématurie/protéinurie, impose une biopsie urgente et un raisonnement étiologique. Les dépôts linéaires orientent vers les anticorps anti-membrane basale, les dépôts granuleux vers les complexes immuns et l’aspect pauci-immun vers les vascularites. Une hémorragie alvéolaire peut accompagner l’atteinte rénale.','Glomérulonéphrites rapidement progressives','La conduite urgente est spécialisée ; ne pas attendre tous les examens lorsqu’une atteinte d’organe menace et ne pas assimiler une sérologie à toute la preuve causale.')
add('EU-POSTINF',C/'FR-GLOM.raw',FG,'CUEN, 12e édition, 2025','pp.186–187 ; GN aiguë postinfectieuse et tests','La forme poststreptococcique typique suit une infection après un intervalle libre, associe syndrome néphritique et baisse fréquente du C3. Une biopsie est discutée si le diagnostic reste incertain. Le pronostic de la forme typique est généralement favorable ; le bilan immunologique est orienté par la clinique.','Forme typique postinfectieuse','Le pronostic pédiatrique typique ne s’étend pas aux adultes fragiles ni à toute infection active. Les dépôts sous-épithéliaux sont décrits avec la précision de la microscopie électronique de KDIGO.')
add('EU-HEMATURIA',C/'FR-HEMATURIA.raw',FH,'CUEN, 12e édition, 2025','pp.118–120','Une urine rouge peut correspondre à du sang, à une hémoprotéine ou à un pigment. Le sédiment confirme les hématies. Dysmorphie et cylindres orientent vers le glomérule ; les caillots évoquent une autre source. L’intensité visible de l’hématurie ne mesure pas la gravité de la maladie.','Adultes et enfants','Le seuil quantitatif français est présenté avec ses unités et ne remplace pas les références du laboratoire suisse ni la morphologie.')
add('EU-IRA',C/'FR-IRA.raw',FA,'CUEN, 12e édition, 2025','pp.253,265–269 ; définition, complications, soutien','L’évolution de créatinine et la diurèse définissent la sévérité aiguë ; les équations de débit estimé sont inadaptées à l’état non stationnaire. Hyperkaliémie, acidose sévère et surcharge pulmonaire sont des complications urgentes. Les diurétiques traitent la surcharge sans accélérer la récupération rénale. Une épuration est nécessaire si les complications graves l’imposent.','Insuffisance rénale aiguë','Les décisions ne reposent pas sur une créatinine isolée. Le tableau CUEN arrondit certains seuils ; une présentation de critères formels doit être confrontée à leur source primaire.')
add('INT-GN-GENERAL',OLD/'KDIGO21.raw',KD,'KDIGO, groupe international, 2021','Points1.1.1–1.1.3,1.2.1–1.2.8,1.3.1–1.3.2 ; pp.S30–S33','La biopsie est la référence pour l’évaluation glomérulaire, avec des exceptions contextualisées. Protéinurie et sédiment doivent être évalués ; le rapport du premier matin est pratique chez l’enfant. Un prélèvement ponctuel varie et ne remplace pas toujours le recueil prolongé lorsque la décision thérapeutique en dépend.','Maladies glomérulaires','Consensus international utilisé après sources suisses et européennes ; aucune recommandation américaine nationale. Les sections non consultées ne sont pas revendiquées.')
add('INT-INFECTION',OLD/'KDIGO21.raw',KD,'KDIGO, groupe international, 2021','Chapitre7 pp.S172–S175, figure57 visualisée PDFp.179','Une glomérulonéphrite peut suivre une infection ou survenir pendant une infection active. Endocardite et infection à staphylocoque peuvent s’accompagner d’ANCA ou de dépôts d’IgA. La biopsie aide si la preuve infectieuse manque ou si le diagnostic est incertain. Les dépôts sous-épithéliaux sont étudiés en microscopie électronique. Le traitement vise infection, œdèmes et hypertension ; les corticoïdes de routine ne sont pas étayés. Le suivi inclut fonction, complément et protéinurie ; un C3 encore bas au-delà de 12 semaines peut justifier une exploration histologique complémentaire.','Glomérulonéphrites liées aux infections bactériennes','Pronostics très différents selon âge, comorbidités et infection ; pas de taux de cohorte transposé à la Suisse. Le délai de complément n’autorise pas à différer une biopsie urgente.')
add('NORMAL-FILTRE',OLD/'OPENSTAX25_4.raw','https://openstax.org/books/anatomy-and-physiology-2e/pages/25-4-microscopic-anatomy-of-the-kidney','OpenStax, Anatomy and Physiology, §25.4','Corpuscule rénal, barrière, tubule proximal, anse et collecteur','Le corpuscule filtre le plasma vers la capsule puis le tubule. Les podocytes entourent les capillaires ; les pédicelles délimitent des fentes. Les segments tubulaires réabsorbent et sécrètent, et le collecteur adapte la réabsorption d’eau sous vasopressine.','Anatomie et physiologie normales','Manuel anatomique, pas recommandation clinique. Figures historiques 2013 sous leur propre licence ; ne pas attribuer la licence actuelle du manuel à une figure différente.')
for i,name,gtin,section,parap,pop,lim in [
 ('FI-LASIX-IV','FI_lasix_iv','7680306300177','Posologie, contre-indications, précautions et mécanisme','Chez adulte et adolescent dès15ans, dose initiale parentérale20–40mg ; œdème pulmonaire40mg IV, réévaluation et éventuelle répétition20–40mg après20min. Injection≤4mg/min,≤2,5mg/min si créatinine>5mg/dL. Enfant<15ans : cas critiques,1mg/kg avec maximum20mg/j selon cette FI. Anurie, hypovolémie et troubles électrolytiques sévères figurent parmi les contre-indications.','Produit injectable exact','Ne pas confondre FI et protocole pédiatrique spécialisé ; ne pas transposer les conseils génériques de potassium à une hyperkaliémie aiguë.'),
 ('FI-LASIX-PO','FI_lasix_po','7680306290010','Posologie, contre-indications et précautions','Comprimé40mg : dose adulte initiale selon FI de20–80mg/j et entretien20–40mg/j ; enfant2mg/kg par voie orale avec maximum40mg/j. Surveillance volémie, pression, créatinine et électrolytes ; anurie et hypovolémie contre-indiquées.','Produit oral exact','Les unités et voies restent distinctes de la préparation injectable ; adaptation à la réponse, sans dose universelle du syndrome néphritique.'),
 ('FI-NORVASC','FI-NORVASC','7680500440174','Indications, posologie, contre-indications, précautions','Amlodipine adulte5mg une fois par jour, jusqu’à10mg selon réponse ; dose initiale parfois moindre chez sujet âgé. Pas d’adaptation rénale habituelle, prudence hépatique. Données insuffisantes avant18ans dans cette FI ; hypotension sévère et choc contre-indiqués.','Norvasc exact, adulte','Traitement de fond ; ne remplace pas la prise en charge hospitalière d’une urgence hypertensive et ne fournit pas ici de prescription pédiatrique.'),
 ('FI-OSPEN','FI-OSPEN','7680370570018','Indications, posologie, contre-indications et précautions','Ospen1000 adulte et adolescent≥12ans : un comprimé3–4fois/j selon FI, au moins10jours pour infection streptococcique ; en anurie intervalle recommandé12h. Contre-indication allergie aux bêta-lactamines ; potassium65,8mg par comprimé1000 à compter en insuffisance rénale.','Produit exact, infection sensible documentée','L’indication réglementaire de prophylaxie des complications ne démontre pas l’efficacité sur une GN déjà établie ; la justification clinique est confrontée à KDIGO. Aucun traitement d’endocardite n’est déduit de ce schéma oral.')]:
 path=(OLD if name.startswith('FI_lasix') else C)/(name+'.raw')
 add(i,path,'https://amiko.oddb.org/fr/fi?gtin='+gtin,'Information professionnelle suisse, Swissmedic/AIPS via AmiKo',section,parap,pop,lim)
add('CH-CIM',OLD/'CIM.raw','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686264/master','OFS, CIM-10-GM2024 français','ClasseN00, blocN00–N08, modificateurS14N00_4 et classes.0–.9','La catégorieN00 désigne le syndrome néphritique aigu ; les suffixes morphologiques.0–.8 supposent normalement une identification précise histologique. Les exclusions comprennent la néphrite tubulo-interstitielle aiguë et le syndrome néphritique sans précision.','Classification administrative suisse2024','Le code ne constitue ni un stade de gravité ni une cause immunologique ; l’annexe suit le raisonnement clinique.')
add('CH-PROFILES',Path('/workspace/medina-source-cache/C85/profiles2017-official.pdf'),'https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','CIMS, PROFILES2017','pp.29 et33 : SSP63,64,161,164,173','Les situations incluent anomalies de la diurèse, hématurie, marqueurs de fonction rénale, sédiment et protéinurie. Elles servent de correspondance pédagogique aux tâches de cette leçon.','Formation médicale suisse','Numérotation2017 ; pas correspondance CIM officielle ni question réelle d’examen ; ne pas mélanger les éditions.')
add('CH-MEBEKO',Path('/workspace/medina-source-cache/C85/mebeko2026.md'),'https://www.bag.admin.ch/dam/fr/sd-web/fL9EvX0YPT2d/20260204_Exigences%20MED%202026_f.pdf','MEBEKO, exigences édictées03.03.2026','§1 et2.1, contenu et blueprint','L’examen2026 comporte connaissances et compétences cliniques et s’appuie sur les objectifs légaux, PROFILES et un blueprint multidimensionnel.','Examen fédéral2026','Empreinte du texte extrait en cache, pas du PDF ; les exercices MEDINA sont originaux et non officiels.')
add('INT-AKI',C/'INT-AKI-provider.txt','https://kdigo.org/wp-content/uploads/2016/10/KDIGO-2012-AKI-Guideline-English.pdf','KDIGO, groupe international, 2012','§2.1, tableau2 ; extrait du fournisseur Parallel réellement lu','L’insuffisance rénale aiguë est définie par une augmentation de créatinine d’au moins26,5µmol/L en48h, ou à au moins1,5fois la valeur de base sur7jours, ou une diurèse inférieure à0,5mL/kg/h sur6h. Le stade retient le critère le plus sévère de créatinine ou diurèse. Les fenêtres diagnostiques ne limitent pas la durée de progression du stade pendant le même épisode.','Définition générale de l’insuffisance rénale aiguë','PDF direct non obtenu (réponse406) ; lecture d’extraits de la source officielle par fournisseur, avec OCR altérant les signes et µ. Unités confrontées au CUEN et conversion88,4µmol/L parmg/dL ; aucun protocole de réanimation2012 repris.')
add('CH-PEDIATRIC-BP',C/'CH-PEDIATRIC-BP.raw','https://www.paediatrieschweiz.ch/fr/hypertension-arterielle-pendant-lenfance/','Betti, Stefani-Glücksberg, Simonetti ; pédiatrie suisse,25.12.2020','Définition, fréquence et mesure de la pression','L’interprétation de la pression pendant l’enfance dépend de l’âge, de la taille et du sexe ; la revue suisse se réfère aux recommandations européennes. Les mesures répétées définissent une hypertension habituelle, sans constituer un motif d’attente devant une atteinte aiguë menaçante.','Enfants et adolescents','Pas de tableau de percentiles reproduit ; ne pas extrapoler les modalités de diagnostic chronique à une urgence néphritique.')
add('CH-PREGNANCY',C/'CH-PREGNANCY.raw','https://www.revmed.ch/view/409725/3594818/RMS_662_1603.pdf','Mégevand et coll., Revue Médicale Suisse2019','pp.1603–1604 ; diagnostic et classification','Une hypertension nouvelle de grossesse associée à une atteinte d’organe, dont l’atteinte rénale, fait rechercher une prééclampsie ; la protéinurie n’est pas obligatoire. L’évaluation relie obstétrique et médecine interne.','Femmes enceintes','Source utilisée pour le diagnostic différentiel et l’orientation, pas pour des seuils thérapeutiques ni des schémas de prescription actualisés.')
(OUT/'source-ledger.json').write_text(json.dumps(dict(code='N00',reader='astra_nephrologie',sources=rows,clinical_certification=False,quote_policy='Paraphrases publiques ; sources intégrales et extraits de travail en cache externe.'),ensure_ascii=False,indent=2)+'\n')
print(len(rows),'lectures ciblées consignées')
